        routes.append(current)

    # Repair: ensure every customer appears once and no missing nodes
    seen = {}
    for r in routes:
        for c in r:
            seen[c] = seen.get(c, 0) + 1
    missing = [c for c in customers_list if c not in seen]
    if missing:
        for c in missing:
            placed = False
            for r in routes:
                if route_load(r) + demand.get(c, 0) <= capacity:
                    r.append(c)
                    placed = True
                    break
            if not placed:
                routes.append([c])

    # Remove duplicates conservatively by first occurrence
    used = set()
    repaired = []
    for r in routes:
        nr = []
        for c in r:
            if c not in used:
                used.add(c)
                nr.append(c)
        if nr:
            repaired.append(nr)
    routes = repaired

    # Local search 1: intra-route nearest-end insertion order (2-opt-like reversal)
    for ri in range(len(routes)):
        r = routes[ri]
        improved = True
        while improved and len(r) >= 4:
            improved = False
            best_gain = 0.0
            best_i = best_j = None
            base = route_cost(r)
            n = len(r)
            for i in range(n - 2):
                for j in range(i + 2, n):
                    if i == 0 and j == n - 1:
                        continue
                    nr = r[:i + 1] + r[i + 1:j + 1][::-1] + r[j + 1:]
                    gain = base - route_cost(nr)
                    if gain > best_gain + 1e-12:
                        best_gain = gain
                        best_i, best_j = i, j
            if best_i is not None:
                r = r[:best_i + 1] + r[best_i + 1:best_j + 1][::-1] + r[best_j + 1:]
                improved = True
        routes[ri] = r

    # Local search 2: relocate customers between routes if it reduces total cost and respects capacity
    changed = True
    while changed:
        changed = False
        best_move = None
        best_delta = 0.0

        for i in range(len(routes)):
            for pos, c in enumerate(routes[i]):
                di = demand.get(c, 0)
                for j in range(len(routes)):
                    if i == j:
                        continue
                    if route_load(routes[j]) + di > capacity:
                        continue
                    ri = routes[i]
                    rj = routes[j]
                    base = route_cost(ri) + route_cost(rj)
                    nri = ri[:pos] + ri[pos + 1:]
                    if not nri:
                        continue
                    for ins in range(len(rj) + 1):
                        nrj = rj[:ins] + [c] + rj[ins:]
                        delta = base - (route_cost(nri) + route_cost(nrj))
                        if delta > best_delta + 1e-12:
                            best_delta = delta
                            best_move = (i, j, pos, ins, c)

        if best_move is not None:
            i, j, pos, ins, c = best_move
            routes[i].pop(pos)
            routes[j] = routes[j][:ins] + [c] + routes[j][ins:]
            routes = [r for r in routes if r]
            changed = True

    # Final cleanup: deterministic order of routes by first customer angle/ID
    def route_key(r):
        first = r[0]
        if depot in coords and first in coords and depot in coords:
            return (dist(depot, first), first)
        return (first,)

    routes.sort(key=route_key)

    return routes
